selector_to_html = {"a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.A_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.A_coolant\">\n<span class=\"sig-name descname\"><span class=\"pre\">A_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.set_channel_angular_width\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.set_channel_angular_width\">\n<span class=\"sig-name descname\"><span class=\"pre\">set_channel_angular_width</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angular_widths_rad</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._build_prof\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._build_prof\">\n<span class=\"sig-name descname\"><span class=\"pre\">_build_prof</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">centerline</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\" title=\"pyskyfire.regen.cross_section.SectionProfiles\"><span class=\"pre\">SectionProfiles</span></a></span></span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.set_channel_height\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.set_channel_height\">\n<span class=\"sig-name descname\"><span class=\"pre\">set_channel_height</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heights</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.__getstate__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.__getstate__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__getstate__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Leave the derived section cache out; it rebuilds on demand.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.wedge_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.wedge_angle\">\n<span class=\"sig-name descname\"><span class=\"pre\">wedge_angle</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.Dh_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.Dh_coolant\">\n<span class=\"sig-name descname\"><span class=\"pre\">Dh_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.n_channels\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.n_channels\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">n_channels</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span></dt><dd><p>Total number of physical channels carrying this circuit\u2019s flow.</p><p>Leaves times channels per leaf. <code class=\"docutils literal notranslate\"><span class=\"pre\">placement.channel_count()</span></code> counts\nleaves only, because it feeds the circumferential packing; a radial\nstack shares a leaf but not a passage, so anything that divides mass\nflow or accumulates volume needs this instead.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._evaluate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._evaluate\">\n<span class=\"sig-name descname\"><span class=\"pre\">_evaluate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">evaluator</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">include_section</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Evaluate a design input over a scalar or array of <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._occluding_channel_counts\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._occluding_channel_counts\">\n<span class=\"sig-name descname\"><span class=\"pre\">_occluding_channel_counts</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the occluding channel count at each station, if knowable.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.precompute_thermal_properties\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.precompute_thermal_properties\">\n<span class=\"sig-name descname\"><span class=\"pre\">precompute_thermal_properties</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Precompute passage geometry along a representative coolant path.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">cross_section_base_point_path</span></code> anchors section geometry;\n<code class=\"docutils literal notranslate\"><span class=\"pre\">cooling_channel_centroid_path</span></code> controls passage length and curvature.</p></dd>", "a[href=\"../cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionProfiles</span></span></dt><dd><p>All geometry profiles along the cooling-channel centerline.</p><p>Each required array must have consistent length <code class=\"docutils literal notranslate\"><span class=\"pre\">N</span></code> (number of stations).</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.section_planes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.section_planes\">\n<span class=\"sig-name descname\"><span class=\"pre\">section_planes</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">reference_path</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axis_normal</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return physical section planes, optionally at a resolved layout seed.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.local_sector_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.local_sector_angle\">\n<span class=\"sig-name descname\"><span class=\"pre\">local_sector_angle</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._design_input_context\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._design_input_context\">\n<span class=\"sig-name descname\"><span class=\"pre\">_design_input_context</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the optional <code class=\"docutils literal notranslate\"><span class=\"pre\">SectionProfiles</span></code> fields, best effort.</p><p>Everything here only feeds design-input functions. A quantity that\ncannot be determined is left out rather than raising, so that a\npartially built circuit can still be asked for plain geometry; a\ndesign input that needs the missing quantity is what raises.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._invalidate_section_cache\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._invalidate_section_cache\">\n<span class=\"sig-name descname\"><span class=\"pre\">_invalidate_section_cache</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Drop the cached section geometry after a change that redefines it.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._prof\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._prof\">\n<span class=\"sig-name descname\"><span class=\"pre\">_prof</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">centerline</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\" title=\"pyskyfire.regen.cross_section.SectionProfiles\"><span class=\"pre\">SectionProfiles</span></a></span></span></dt><dd><p>Build a SectionProfiles with trivial frames (analytics don\u2019t use them).</p><p>The bundle is pure geometry, so it is cached against the path it was\nbuilt from and reused until <a class=\"reference internal\" href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._invalidate_section_cache\" title=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._invalidate_section_cache\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">_invalidate_section_cache()</span></code></a> drops it.\nAssembling one walks every station of every wall, evaluating any\ndesign-input function a station at a time, and the solver reaches a\nsingle station through <a class=\"reference internal\" href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.section_profiles_at\" title=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.section_profiles_at\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">section_profiles_at()</span></code></a> on every residual\nit forms, so rebuilding it there dominated the whole simulation.</p><p>Staleness is bounded the same way the <code class=\"docutils literal notranslate\"><span class=\"pre\">*_vals</span></code> arrays that\n<a class=\"reference internal\" href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.precompute_thermal_properties\" title=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.precompute_thermal_properties\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">precompute_thermal_properties()</span></code></a> writes are: change the geometry\nand you have to rebuild, which for the profile setters happens\nautomatically and for a wholesale path swap falls out of the path no\nlonger being the one the bundle was built from.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_full_heights\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_full_heights\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">channel_full_heights</span></span></dt><dd><p>Full internal coolant heights on <code class=\"docutils literal notranslate\"><span class=\"pre\">x_domain</span></code> [m], for reporting.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.R_coolant_per_len\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.R_coolant_per_len\">\n<span class=\"sig-name descname\"><span class=\"pre\">R_coolant_per_len</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_c</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_wall_rep</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Effective coolant-side thermal resistance per unit <em>axial length</em> [K m / W].</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_height\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_height\">\n<span class=\"sig-name descname\"><span class=\"pre\">channel_height</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the supplied height [m], using the section\u2019s input convention.</p><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">channel_full_heights</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">channel_base_heights</span></code> to report\nresolved physical heights on <code class=\"docutils literal notranslate\"><span class=\"pre\">x_domain</span></code> after chamber assembly.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.total_thickness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.total_thickness\">\n<span class=\"sig-name descname\"><span class=\"pre\">total_thickness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the full hot-to-coolant stack thickness, including liners.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_wall_thickness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_wall_thickness\">\n<span class=\"sig-name descname\"><span class=\"pre\">channel_wall_thickness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the combined main-wall thickness used for channel geometry.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.set_channel_local_sector\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.set_channel_local_sector\">\n<span class=\"sig-name descname\"><span class=\"pre\">set_channel_local_sector</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">local_sectors</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.section_profiles_at\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.section_profiles_at\">\n<span class=\"sig-name descname\"><span class=\"pre\">section_profiles_at</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\" title=\"pyskyfire.regen.cross_section.SectionProfiles\"><span class=\"pre\">SectionProfiles</span></a></span></span></dt><dd><p>Interpolate the resolved physical section on the solver grid.</p><p>Cached per station, because the solver holds <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> fixed while it\niterates one wall node\u2019s temperatures and so asks for the same station\nrepeatedly. Sharing the profile also shares the geometry each section\nmemoises on it; see <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">SectionProfiles.cached()</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.bind_chamber\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.bind_chamber\">\n<span class=\"sig-name descname\"><span class=\"pre\">bind_chamber</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Attach the owning chamber, which supplies cross-circuit counts.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.finalize\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.finalize\">\n<span class=\"sig-name descname\"><span class=\"pre\">finalize</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._section_provider_values\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._section_provider_values\">\n<span class=\"sig-name descname\"><span class=\"pre\">_section_provider_values</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Interpolate whichever section quantities have been built at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p><p>Anything not built yet comes back as <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code> and is then omitted from\nthe context, which is what makes the later part of tier C unavailable\nto slots that are evaluated earlier in the geometry build.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._wall_thickness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._wall_thickness\">\n<span class=\"sig-name descname\"><span class=\"pre\">_wall_thickness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">role</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.__setstate__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.__setstate__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__setstate__</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Load circuits serialized before the angular-width rename.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.thrust_chamber.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CoolingCircuit</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">contour</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cross_section</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#list\" title=\"(in Python v3.15)\"><span class=\"pre\">list</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">placement</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">channel_height</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">walls</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">coolant_transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hot_gas_surface_area_multiplier</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outer_walls</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">enable_fin</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rib_material</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Simulation-only representation of a cooling circuit.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">walls</span></code> are ordered from hot gas to coolant. Any <code class=\"docutils literal notranslate\"><span class=\"pre\">role=\"liner\"</span></code>\nlayers precede the main layers; at least one main layer is required.\nWall-like objects without a role are treated as main layers.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">enable_fin=True</span></code> enables this circuit\u2019s rib/fin heat-transfer model.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">rib_material</span></code> optionally supplies its material (with <code class=\"docutils literal notranslate\"><span class=\"pre\">get_k(T)</span></code>).\nWhen omitted, the coolant-facing main-wall material is used. Disabling\nfins removes their thermal enhancement, not their channel geometry.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.roughness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.roughness\">\n<span class=\"sig-name descname\"><span class=\"pre\">roughness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the absolute channel roughness [m] at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.dA_dx_thermal_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.dA_dx_thermal_coolant\">\n<span class=\"sig-name descname\"><span class=\"pre\">dA_dx_thermal_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.dA_dx_thermal_exhaust\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.dA_dx_thermal_exhaust\">\n<span class=\"sig-name descname\"><span class=\"pre\">dA_dx_thermal_exhaust</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.outer_wall_thickness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.outer_wall_thickness\">\n<span class=\"sig-name descname\"><span class=\"pre\">outer_wall_thickness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the combined thickness of the cold-side outer liners [m].</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_base_heights\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.channel_base_heights\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">channel_base_heights</span></span></dt><dd><p>Rounded base heights on <code class=\"docutils literal notranslate\"><span class=\"pre\">x_domain</span></code> [m]; full heights for squared.</p></dd>", "a[href=\"../design_inputs/DesignContext.html#pyskyfire.regen.design_inputs.DesignContext\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.design_inputs.DesignContext\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.design_inputs.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DesignContext</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">providers</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Mapping</span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"pre\">Any</span><span class=\"p\"><span class=\"pre\">]</span></span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">Mapping</span></code></p><p>Lazily evaluated bundle of design-input quantities at one station.</p><p>Providers are either plain values or zero-argument callables.  A callable\nis invoked at most once, the first time its name is requested, so building\na context for a station that only needs <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> costs nothing.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.hot_gas_surface_area_multiplier\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.hot_gas_surface_area_multiplier\">\n<span class=\"sig-name descname\"><span class=\"pre\">hot_gas_surface_area_multiplier</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the circuit-specific effective hot-side area multiplier.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._section_cache_for\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._section_cache_for\">\n<span class=\"sig-name descname\"><span class=\"pre\">_section_cache_for</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">centerline</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return <code class=\"docutils literal notranslate\"><span class=\"pre\">(path,</span> <span class=\"pre\">bundle,</span> <span class=\"pre\">stations)</span></code> for <code class=\"docutils literal notranslate\"><span class=\"pre\">centerline</span></code>, building it once.</p><p>The single-station profiles live in the same entry as the bundle they\nwere interpolated from, so swapping the path cannot leave stations\nbehind that describe the old geometry.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.radius_of_curvature\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.radius_of_curvature\">\n<span class=\"sig-name descname\"><span class=\"pre\">radius_of_curvature</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.set_x_domain\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.set_x_domain\">\n<span class=\"sig-name descname\"><span class=\"pre\">set_x_domain</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x_domain</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.design_context\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.design_context\">\n<span class=\"sig-name descname\"><span class=\"pre\">design_context</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">include_section</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../design_inputs/DesignContext.html#pyskyfire.regen.design_inputs.DesignContext\" title=\"pyskyfire.regen.design_inputs.DesignContext\"><span class=\"pre\">DesignContext</span></a></span></span></dt><dd><p>Build the design-input context for this circuit at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._channels_all_circuits_provider\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._channels_all_circuits_provider\">\n<span class=\"sig-name descname\"><span class=\"pre\">_channels_all_circuits_provider</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire-regen-thrust-chamber-coolingcircuit\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.thrust_chamber.CoolingCircuit<a class=\"headerlink\" href=\"#pyskyfire-regen-thrust-chamber-coolingcircuit\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit._build_section_profiles_at\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit._build_section_profiles_at\">\n<span class=\"sig-name descname\"><span class=\"pre\">_build_section_profiles_at</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../cross_section/SectionProfiles.html#pyskyfire.regen.cross_section.SectionProfiles\" title=\"pyskyfire.regen.cross_section.SectionProfiles\"><span class=\"pre\">SectionProfiles</span></a></span></span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.compute_volume\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.compute_volume\">\n<span class=\"sig-name descname\"><span class=\"pre\">compute_volume</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Set <code class=\"docutils literal notranslate\"><span class=\"pre\">self.volume</span></code>: the wetted coolant volume of the circuit [m\u00b3].</p><p>One channel encloses <span class=\"math notranslate nohighlight\">\\(\\int A\\,ds\\)</span> along its own centreline, so\nthe circuit holds <span class=\"math notranslate nohighlight\">\\(n_{chan}\\int A\\,(ds/dx)\\,dx\\)</span>.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">A_coolant</span></code> is the flow area in the plane normal to the <em>reference\npath</em>, not an axial slice, so it is that path\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">ds/dx</span></code> the area is\nswept along here. <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">ThrustChamber.build_channel_angular_widths()</span></code>\nnarrows the sector by <span class=\"math notranslate nohighlight\">\\(\\cos\\gamma\\)</span> for a helix angle\n<span class=\"math notranslate nohighlight\">\\(\\gamma\\)</span>, while <code class=\"docutils literal notranslate\"><span class=\"pre\">ds/dx</span></code> lengthens the path by the reciprocal\non a cylinder. A helical circuit therefore encloses the same volume as\nan axial one of the same azimuthal pitch, which is the physically\ncorrect answer \u2013 only the path is longer and the section\ncorrespondingly narrower. <code class=\"docutils literal notranslate\"><span class=\"pre\">ds_dx_vals</span></code> follows the coolant centroid\ninstead, which sits further out and so runs slightly further still;\npairing it with the section area would make the swept volume depend on\nthe helix angle.</p><p>Trapezoidal on the circuit\u2019s own <code class=\"docutils literal notranslate\"><span class=\"pre\">x_domain</span></code>, so the result converges\nwith axial resolution rather than being exact at any given <code class=\"docutils literal notranslate\"><span class=\"pre\">n_nodes</span></code>.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.dA_dx_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.dA_dx_coolant\">\n<span class=\"sig-name descname\"><span class=\"pre\">dA_dx_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.hot_side_layer_thickness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.hot_side_layer_thickness\">\n<span class=\"sig-name descname\"><span class=\"pre\">hot_side_layer_thickness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the combined thickness of explicitly marked hot-side liners.</p></dd>", "a[href=\"#pyskyfire.regen.thrust_chamber.CoolingCircuit.ds_dx\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.CoolingCircuit.ds_dx\">\n<span class=\"sig-name descname\"><span class=\"pre\">ds_dx</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
